588	// RecordPayment 为指定账单登记一笔大于零且不超过余额的本地付款，支持分次登记。
589	// 付款标识在同一账户内去重：相同账单和金额的重报仍成功，但本次不再登记
590	// （Registered 为 false），也不再次增加已付金额；返回的付款内容、账单余额与
591	// 付清状态均为该笔付款首次成功登记完成时的历史结果，不随后续付款或账单当前
592	// 状态变化（例如账单后来已结清，重报早先的部分付款仍返回当时的未清余额与
593	// 未付清）。账单查询与账户状态中的余额始终反映当前状态，不受重报影响。
594	// 相同标识但账期或金额不同返回 ErrPaymentConflict：即使原账单已结清，或改指
595	// 向的账期还没有账单，也按冲突处理而非当作新付款。失败不消耗付款标识。
596	func (s *Service) RecordPayment(accountID, paymentID string, period Month, amount int64) (PaymentResult, error) {
597		if accountID == "" {
598			return PaymentResult{}, invalidf("account id is empty")
599		}
600		if paymentID == "" {
601			return PaymentResult{}, invalidf("payment id is empty")
602		}
603		if amount <= 0 {
604			return PaymentResult{}, invalidf("payment %q amount must be positive, got %d", paymentID, amount)
605		}
606		s.mu.Lock()
607		defer s.mu.Unlock()
608	
609		acc, ok := s.accounts[accountID]
610		if !ok {
611			return PaymentResult{}, ErrAccountNotFound
612		}
613		// 去重先于账单查找：相同标识改指向其他账单（哪怕不存在）也是冲突。
614		if prev, ok := acc.payments[paymentID]; ok {
615			if prev.period != period || prev.amount != amount {
616				return PaymentResult{}, ErrPaymentConflict
617			}
618			// 完全相同的重报仍成功，但不再次登记、不改变账单：
619			// 返回这笔付款首次成功登记完成时的余额与付清状态，
620			// 不受账单后续收款、当前余额或停用/恢复状态影响。
621			return PaymentResult{
622				Registered:  false,
623				Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
624				BillBalance: prev.balance,
625				Settled:     prev.settled,
626			}, nil
627		}
628	
629		rec, ok := acc.bills[period]
630		if !ok {
631			return PaymentResult{}, ErrBillNotFound
632		}
633	
634		if amount > rec.bill.Balance {
635			return PaymentResult{}, ErrPaymentExceedsBalance
636		}
637	
638		paid, ok := addNonNeg(rec.bill.Paid, amount)
639		if !ok {
640			return PaymentResult{}, ErrOverflow
641		}
642		rec.bill.Paid = paid
643		rec.bill.Balance -= amount
644		if rec.bill.Balance == 0 {
645			rec.bill.Settled = true
646		}
647		// 保存首次登记完成时的历史结果，供完全相同重报原样返回。
648		acc.payments[paymentID] = paymentRecord{
649			period:  period,
650			amount:  amount,
651			balance: rec.bill.Balance,
652			settled: rec.bill.Settled,
653		}
654	
655		return PaymentResult{
656			Registered:  true,
657			Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
658			BillBalance: rec.bill.Balance,
659			Settled:     rec.bill.Settled,
660		}, nil
661	}
